import{_ as r,a0 as p,w as l,s,I as o,x as e,a1 as i,A as a,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"如何在Linux中用命令列工具管理KVM虛擬環境 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux中用命令列工具管理KVM虛擬環境 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux中用命令列工具管理KVM虛擬環境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux中用命令列工具管理KVM虛擬環境 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150302 How to Manage KVM Virtual Environment using Commandline Tools in Linux","title":"如何在Linux中用命令列工具管理KVM虛擬環境","tag":"201505","desc":""},"relativePath":"201505/20150302 How to Manage KVM Virtual Environment using Commandline Tools in Linux.md","filePath":"[post].md"}'),d={name:"201505/20150302 How to Manage KVM Virtual Environment using Commandline Tools in Linux.md"};function u(g,t,c,h,w,v){const n=p("Link");return l(),s("div",null,[t[18]||(t[18]=o("h1",{id:"如何在linux中用命令列工具管理kvm虛擬環境",tabindex:"-1"},[e("如何在Linux中用命令列工具管理KVM虛擬環境 "),o("a",{class:"header-anchor",href:"#如何在linux中用命令列工具管理kvm虛擬環境","aria-label":"Permalink to “如何在Linux中用命令列工具管理KVM虛擬環境”"},"​")],-1)),o("p",null,[t[1]||(t[1]=e("在我們",-1)),i(n,{href:"http://www.tecmint.com/install-and-configure-kvm-in-linux/"},{default:a(()=>[...t[0]||(t[0]=[e("KVM系列專題",-1)])]),_:1}),t[2]||(t[2]=e("的第四部分，我們將會一起討論下在命令列界面下來管理KVM環境。我們分別用‘virt-install’和virsh命令列工具來創建並配置虛擬機和存儲池，用qemu-img命令列工具來創建並管理磁盤映像。",-1))]),t[19]||(t[19]=m(`<p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/KVM-Management-in-Linux.jpg" alt="KVM Management in Linux"></p><p><em>Linux系統的KVM管理</em></p><p>在這篇文章裏沒有什麼新的概念，我們只是用命令列工具重複之前所做過的事情，也沒有什麼前提條件，都是相同的過程，之前的文章我們都討論過。</p><h3 id="第一步-配置存儲池" tabindex="-1">第一步: 配置存儲池 <a class="header-anchor" href="#第一步-配置存儲池" aria-label="Permalink to “第一步: 配置存儲池”">​</a></h3><p>Virsh命令列工具是一款管理virsh客户域的用户界面。virsh程序能在命令列中運行所給的命令以及它的參數。</p><p>本節中，我們要用它給我們的KVM環境創建存儲池。想知道關於這個工具的更多信息，用以下這條命令。</p><pre><code># man virsh
</code></pre><p><strong>1. 用virsh帶pool-define-as的命令來定義新的存儲池，你需要指定名字、類型和類型參數。</strong></p><p>本例中，我們將名字取為Spool1，類型為目錄。默認情況下你可以提供五個參數給該類型：</p><ul><li>source-host</li><li>source-path</li><li>source-dev</li><li>source-name</li><li>target</li></ul><p>對於目錄類型，我們需要用最後一個參數“target”來指定存儲池的路徑，其它參數項我們可以用“-”來填充。</p><pre><code># virsh pool-define-as Spool1 dir - - - - &quot;/mnt/personal-data/SPool1/&quot;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Create-New-Storage-Pool.png" alt="Create New Storage Pool"></p><p><em>創建新存儲池</em></p><p><strong>2. 查看環境中我們所有的存儲池，用以下命令。</strong></p><pre><code># virsh pool-list --all
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/List-All-Storage-Pools.png" alt="List All Storage Pools"></p><p><em>列出所有存儲池</em></p><p><strong>3. 現在我們來構造存儲池了，用以下命令來構造我們剛才定義的存儲池。</strong></p><pre><code># virsh pool-build Spool1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Build-Storage-Pool.png" alt="Build Storage Pool"></p><p><em>構造存儲池</em></p><p><strong>4. 用帶pool-start參數的virsh命令來激活並啓動我們剛才創建並構造完成的存儲池。</strong></p><pre><code># virsh pool-start Spool1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Active-Storage-Pool.png" alt="Active Storage Pool"></p><p><em>激活存儲池</em></p><p><strong>5. 查看環境中存儲池的狀態，用以下命令。</strong></p><pre><code># virsh pool-list --all
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Check-Storage-Pool-Status.png" alt="Check Storage Pool Status"></p><p><em>查看存儲池狀態</em></p><p>你會發現Spool1的狀態變成了已激活。</p><p><strong>6. 對Spool1進行配置，讓它每次都能被libvirtd服務自啓動。</strong></p><pre><code># virsh pool-autostart Spool1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Configure-Storage-Pool.png" alt="Configure KVM Storage Pool"></p><p><em>配置KVM存儲池</em></p><p><strong>7. 最後來看看我們新的存儲池的信息吧。</strong></p><pre><code># virsh pool-info Spool1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Check-Storage-Pool-Information.png" alt="Check KVM Storage Pool Information"></p><p><em>查看KVM存儲池信息</em></p><p>恭喜你，Spool1已經準備好待命，接下來我們試着創建存儲捲來使用它。</p><h3 id="第二步-配置存儲卷-磁盤映像" tabindex="-1">第二步: 配置存儲卷/磁盤映像 <a class="header-anchor" href="#第二步-配置存儲卷-磁盤映像" aria-label="Permalink to “第二步: 配置存儲卷/磁盤映像”">​</a></h3><p>現在輪到磁盤映像了，用qemu-img命令在Spool1中創建一個新磁盤映像。獲取更多細節信息，可以查看man手冊。</p><pre><code># man qemu-img
</code></pre><p><strong>8. 我們應該在qemu-img命令之後指定“create, check,…”等等操作、磁盤映像格式、你想要創建的磁盤映像的路徑和大小。</strong></p><pre><code># qemu-img create -f raw /mnt/personal-data/SPool1/SVol1.img 10G
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Create-Storage-Volumes.png" alt="Create Storage Volume"></p><p><em>創建存儲卷</em></p><p><strong>9. 通過使用帶info的qemu-img命令，你可以獲取到你的新磁盤映像的一些信息。</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Check-Storage-Volume-Information.png" alt="Check Storage Volume Information"></p><p><em>查看存儲卷信息</em></p><p><strong>警告</strong>: 不要用qemu-img命令來修改被運行中的虛擬機或任何其它進程所正在使用的映像，那樣映像會被破壞。</p><p>現在是時候來創建虛擬機了。</p><h3 id="第三步-創建虛擬機" tabindex="-1">第三步: 創建虛擬機 <a class="header-anchor" href="#第三步-創建虛擬機" aria-label="Permalink to “第三步: 創建虛擬機”">​</a></h3><p><strong>10. 現在到最後一個環節了，在最後一步中，我們將用virt-install命令來創建虛擬機。virt-install是一個用來創建新的KVM虛擬機命令列工具，它使用“libvirt”管理程序庫。想獲取更多細節，同樣可以查看man手冊。</strong></p><pre><code># man virt-install
</code></pre><p>要創建新的KVM虛擬機，你需要用到帶以下所有信息的命令。</p><ul><li><p>Name: 虛擬機的名字。</p></li><li><p>Disk Location: 磁盤映像的位置。</p></li><li><p>Graphics : 怎樣連接VM，通常是SPICE。</p></li><li><p>vcpu : 虛擬CPU的數量。</p></li><li><p>ram : 以兆字節計算的已分配內存大小。</p></li><li><p>Location : 指定安裝源路徑。</p></li><li><p>Network : 指定虛擬網絡，通常是virbr0網橋。</p><h1 id="virt-install-name-rhel7-disk-path-mnt-personal-data-spool1-svol1-img-graphics-spice-vcpu-1-ram-1024-location-run-media-dos-9e6f605a-f502-4e98-826e-e6376caea288-rhel-server-7-0-x86-64-dvd-iso-network-bridge-virbr0" tabindex="-1">virt-install --name=rhel7 --disk path=/mnt/personal-data/SPool1/SVol1.img --graphics spice --vcpu=1 --ram=1024 --location=/run/media/dos/9e6f605a-f502-4e98-826e-e6376caea288/rhel-server-7.0-x86_64-dvd.iso --network bridge=virbr0 <a class="header-anchor" href="#virt-install-name-rhel7-disk-path-mnt-personal-data-spool1-svol1-img-graphics-spice-vcpu-1-ram-1024-location-run-media-dos-9e6f605a-f502-4e98-826e-e6376caea288-rhel-server-7-0-x86-64-dvd-iso-network-bridge-virbr0" aria-label="Permalink to “virt-install --name=rhel7 --disk path=/mnt/personal-data/SPool1/SVol1.img --graphics spice --vcpu=1 --ram=1024 --location=/run/media/dos/9e6f605a-f502-4e98-826e-e6376caea288/rhel-server-7.0-x86_64-dvd.iso --network bridge=virbr0”">​</a></h1></li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Create-New-Virtual-Machines.png" alt="Create New Virtual Machine"></p><p><em>創建新的虛擬機</em></p><p><strong>11. 你會看到彈出一個virt-vierwer窗口，像是在通過它在與虛擬機通信。</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Booting-Virtual-Machine.jpeg" alt="Booting Virtual Machine"></p><p><em>虛擬機啓動程式</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Installation-of-Virtual-Machine.jpeg" alt="Installation of Virtual Machine"></p><p><em>虛擬機安裝過程</em></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>以上就是我們KVM教程的最後一部分了，當然我們還沒有完全覆蓋到全部，我們只是打了個擦邊球，所以現在該輪到你來好好地利用這些豐富的資源來做自己想做的事了。</p>`,66)),o("ul",null,[o("li",null,[i(n,{href:"https://access.redhat.com/site/documentation/en-US/Red_Hat_Enterprise_Linux/7/html/Virtualization_Getting_Started_Guide/index.html"},{default:a(()=>[...t[3]||(t[3]=[e("KVM Getting Started Guide",-1)])]),_:1})]),o("li",null,[i(n,{href:"https://access.redhat.com/site/documentation/en-US/Red_Hat_Enterprise_Linux/7/html/Virtualization_Deployment_and_Administration_Guide/index.html"},{default:a(()=>[...t[4]||(t[4]=[e("KVM Virtualization Deployment and Administration Guide",-1)])]),_:1})])]),t[20]||(t[20]=o("hr",null,null,-1)),o("p",null,[t[6]||(t[6]=e("via: ",-1)),i(n,{href:"http://www.tecmint.com/kvm-management-tools-to-manage-virtual-machines/"},{default:a(()=>[...t[5]||(t[5]=[e("http://www.tecmint.com/kvm-management-tools-to-manage-virtual-machines/",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("作者：",-1)),i(n,{href:"http://www.tecmint.com/author/dos2009/"},{default:a(()=>[...t[7]||(t[7]=[e("Mohammad Dosoukey",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),i(n,{href:"https://github.com/ZTinoZ"},{default:a(()=>[...t[8]||(t[8]=[e("ZTinoZ",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:a(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[15]||(t[15]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創翻譯，",-1)),i(n,{href:"http://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const x=r(d,[["render",u]]);export{S as __pageData,x as default};
